import { useState } from "react";
import axios from "axios";

const BACKEND_URL = process.env.NEXT_PUBLIC_BACKEND_URL;

const UserProfileForm = ({ user, setUser, fetchUserProfile }) => {
  const [loading, setLoading] = useState(false);
  const [previewImage, setPreviewImage] = useState(user.photoProfileUrl || "");
  
  const handleChange = (e) => {
    setUser({ ...user, [e.target.name]: e.target.value });
  };
  
  const handleUpdateProfile = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        console.error("User not authenticated");
        setLoading(false);
        return;
      }
      
      await axios.put(`${BACKEND_URL}/api/v1/user/profile`, {
        fullname: user.fullname,
        birthDate: user.birthDate,
        gender: user.gender,
      }, {
        headers: { Authorization: `Bearer ${token}` },
      });
      alert("Profile updated successfully!");
      fetchUserProfile();
    } catch (error) {
      console.error("Failed to update profile:", error);
    } finally {
      setLoading(false);
    }
  };
  
  const handleUploadPhoto = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const allowedTypes = ["image/jpeg", "image/jpg", "image/png", "image/gif"];
    if (!allowedTypes.includes(file.type)) {
      alert("Only JPG, JPEG, PNG, and GIF files are allowed.");
      return;
    }
    if (file.size > 1024 * 1024) {
      alert("File size must be less than 1MB.");
      return;
    }

    const formData = new FormData();
    formData.append("file", file);

    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        console.error("User not authenticated");
        return;
      }
      
      const response = await axios.post(`${BACKEND_URL}/api/v1/user/upload-avatar`, formData, {
        headers: { Authorization: `Bearer ${token}` },
      });
      
      setUser((prev) => ({ ...prev, photoProfileUrl: response.data.data.secureUrl }));
      setPreviewImage(URL.createObjectURL(file));
      alert("Profile picture updated!");
    } catch (error) {
      console.error("Failed to upload profile picture:", error);
    }
  };
  
  return (
    <div className="p-6 border rounded-lg shadow-md bg-gray-100">
      <h2 className="text-xl font-semibold mb-4">Edit Profile</h2>
      <label className="block mb-2">Full Name</label>
      <input 
        type="text" 
        name="fullname" 
        value={user.fullname} 
        onChange={handleChange} 
        className="border p-2 w-full rounded mb-4" 
      />
      <label className="block mb-2">Birth Date</label>
      <input 
        type="date" 
        name="birthDate" 
        value={user.birthDate} 
        onChange={handleChange} 
        className="border p-2 w-full rounded mb-4" 
      />
      <label className="block mb-2">Gender</label>
      <select 
        name="gender" 
        value={user.gender} 
        onChange={handleChange} 
        className="border p-2 w-full rounded mb-4"
      >
        <option value="">Select Gender</option>
        <option value="male">Male</option>
        <option value="female">Female</option>
      </select>
      <button 
        className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600" 
        onClick={handleUpdateProfile} 
        disabled={loading}
      >
        {loading ? "Updating..." : "Update Profile"}
      </button>
      <h2 className="text-xl font-semibold mt-6 mb-2">Profile Picture</h2>
      <img
        src={previewImage || user.photoProfileUrl || "/default-avatar.png"}
        alt="Profile"
        className="w-24 h-24 rounded-full mb-4 object-cover border"
      />
      <input 
        type="file" 
        accept=".jpg,.jpeg,.png,.gif" 
        className="border p-2 w-full rounded mb-4"
        onChange={handleUploadPhoto}
      />
    </div>
  );
};

export default UserProfileForm;
